def check_winner(self):
    """
    Check if there is a winner on the board in rows, columns and diagonals three directions
    :return: str or None, the mark of the winner ('X' or 'O'), or None if there is no winner yet
    >>> moves = [(1, 0), (2, 0), (1, 1), (2, 1), (1, 2)]
    >>> for move in moves:
    ...     ttt.make_move(move[0], move[1])
    >>> ttt.check_winner()
    'X'
    """
    rows = len(self.board)
    cols = len(self.board[0]) if self.board else 0

    # Check rows
    for row in range(rows):
        if all(self.board[row][col] != ' ' and self.board[row][col] == self.board[row][0] for col in range(1, cols)):
            if self.board[row][0] != ' ':
                return self.board[row][0]

    # Check columns
    for col in range(cols):
        if all(self.board[row][col] != ' ' and self.board[row][col] == self.board[0][col] for row in range(1, rows)):
            if self.board[0][col] != ' ':
                return self.board[0][col]

    # Check main diagonal (only if square board)
    if rows == cols:
        if all(self.board[i][i] != ' ' for i in range(rows)):
            return self.board[0][0]

    # Check anti-diagonal (only if square board)
    if rows == cols:
        if all(self.board[i][rows - 1 - i] != ' ' for i in range(rows)):
            return self.board[0][rows - 1]

    return None

